PRAGMA defer_foreign_keys=ON;
CREATE TABLE family_notification_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES family_notification_versions(id) DEFERRABLE INITIALLY DEFERRED,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),recipient_id TEXT NOT NULL REFERENCES users(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('publish','withdraw')),title TEXT NOT NULL,public_note TEXT NOT NULL,internal_reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence));
CREATE VIEW family_notification_current AS SELECT v.* FROM family_notification_versions v WHERE revision=(SELECT max(revision) FROM family_notification_versions WHERE root_id=v.root_id);
CREATE TABLE family_notification_receipts(id TEXT PRIMARY KEY,version_id TEXT NOT NULL UNIQUE REFERENCES family_notification_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),recipient_id TEXT NOT NULL REFERENCES users(id),notification_sequence INTEGER NOT NULL CHECK(notification_sequence>0),created_at TEXT NOT NULL);
CREATE TRIGGER family_notification_version_source BEFORE INSERT ON family_notification_versions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM customers WHERE id=NEW.customer_id AND store_id=NEW.store_id AND created_at<=NEW.created_at) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM family_notification_versions WHERE store_id=NEW.store_id),1) OR NEW.revision=1 AND (NEW.root_id<>NEW.id OR NEW.action<>'publish') OR NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM family_notification_current c JOIN family_notification_versions r ON r.id=c.root_id WHERE c.root_id=NEW.root_id AND NEW.revision=c.revision+1 AND r.store_id=NEW.store_id AND r.customer_id=NEW.customer_id AND r.recipient_id=NEW.recipient_id AND (NEW.action='publish' OR c.action='publish')) THEN RAISE(ABORT,'family notification fixed original continuous source') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role IN('manager','reception') AND coalesce(s.must_change_password,0)=0) OR NEW.action='publish' AND NOT EXISTS(SELECT 1 FROM users u JOIN guardian_links g ON g.user_id=u.id LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.recipient_id AND u.role='guardian' AND u.active=1 AND g.customer_id=NEW.customer_id AND g.active=1 AND coalesce(s.must_change_password,0)=0) THEN RAISE(ABORT,'family notification current staff/recipient authorization') END;
END;
CREATE TRIGGER family_notification_receipt_source BEFORE INSERT ON family_notification_receipts BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM family_notification_versions WHERE store_id=NEW.store_id AND sequence<=NEW.notification_sequence AND created_at>NEW.created_at) OR NEW.notification_sequence IS NOT (SELECT max(sequence) FROM family_notification_versions WHERE store_id=NEW.store_id) OR NOT EXISTS(SELECT 1 FROM family_notification_versions v JOIN users u ON u.id=v.recipient_id JOIN guardian_links g ON g.customer_id=v.customer_id AND g.user_id=u.id LEFT JOIN user_security s ON s.user_id=u.id WHERE v.id=NEW.version_id AND v.action='publish' AND v.store_id=NEW.store_id AND v.recipient_id=NEW.recipient_id AND v.created_at<=NEW.created_at AND u.active=1 AND u.role='guardian' AND g.active=1 AND coalesce(s.must_change_password,0)=0 AND NOT EXISTS(SELECT 1 FROM family_notification_versions w WHERE w.root_id=v.root_id AND w.action='withdraw' AND w.revision>=v.revision)) THEN RAISE(ABORT,'family notification explicit currently authorized original read') END;
END;
CREATE TRIGGER family_notification_version_text BEFORE INSERT ON family_notification_versions WHEN length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 OR length(trim(NEW.public_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.public_note)>2000 OR instr(NEW.public_note,char(0))>0 OR length(trim(NEW.internal_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.internal_reason)>300 OR instr(NEW.internal_reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'family notification separate public/internal text');END;
CREATE TRIGGER family_notification_versions_time BEFORE INSERT ON family_notification_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_notification_versions WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family notification canonical nondecreasing time');END;
CREATE TRIGGER family_notification_versions_no_update BEFORE UPDATE ON family_notification_versions BEGIN SELECT RAISE(ABORT,'family notification immutable');END;
CREATE TRIGGER family_notification_versions_no_delete BEFORE DELETE ON family_notification_versions BEGIN SELECT RAISE(ABORT,'family notification immutable');END;
CREATE TRIGGER family_notification_receipts_time BEFORE INSERT ON family_notification_receipts WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM family_notification_receipts WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'family notification canonical nondecreasing time');END;
CREATE TRIGGER family_notification_receipts_no_update BEFORE UPDATE ON family_notification_receipts BEGIN SELECT RAISE(ABORT,'family notification immutable');END;
CREATE TRIGGER family_notification_receipts_no_delete BEFORE DELETE ON family_notification_receipts BEGIN SELECT RAISE(ABORT,'family notification immutable');END;
